if(isset($_POST['room_save'])){$id=(int)$_POST['id'];$st=$conn->prepare("UPDATE rooms SET quantity=?,price=? WHERE id=?");$st->bind_param("idi",$_POST['quantity'],$_POST['price'],$id);$st->execute();}
